/* Prinsip Sistem: pita cahaya bergerak di belakang hexagon yang tetap diam. */
.lp-panel{isolation:isolate;background:radial-gradient(ellipse at 100% 100%,#08667c70,transparent 65%),linear-gradient(130deg,#0b2d47,#061a30)}
.lp .lp-wave-art{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0;opacity:.7}
.lp-wave-band{transform-box:view-box;transform-origin:center;will-change:transform}
.lp-wave-one{animation:lp-wave-drift-a 13s ease-in-out infinite alternate}
.lp-wave-two{animation:lp-wave-drift-b 17s ease-in-out infinite alternate}
.lp-wave-three{animation:lp-wave-drift-a 19s ease-in-out -6s infinite alternate;opacity:.6}
@keyframes lp-wave-drift-a{from{transform:translate(-30px,-14px) scaleY(.9)}to{transform:translate(38px,22px) scaleY(1.09)}}
@keyframes lp-wave-drift-b{from{transform:translate(34px,25px) scaleY(1.08)}to{transform:translate(-32px,-16px) scaleY(.92)}}
.lp-panel-top,.lp-metrics,.lp-panel-foot{position:relative;z-index:1}
.lp-panel-top>div:last-child{background:radial-gradient(ellipse,#08283b99,transparent 85%)}
.lp-emblem{align-items:center;justify-content:center;padding-top:0;min-height:150px}
.lp-hex{width:108px;max-width:100%;height:124px;flex-shrink:0}
.lp-hex:after{background:linear-gradient(145deg,#0d3049ed,#071d30f5)}
.lp-metrics:before{content:"";position:absolute;top:-1px;left:0;width:22%;height:2px;background:linear-gradient(90deg,transparent,#87f5ff,transparent);filter:drop-shadow(0 0 4px #24e4ff);animation:lp-divider-glide 7s ease-in-out infinite}
@keyframes lp-divider-glide{0%,100%{transform:translateX(0);opacity:.25}50%{transform:translateX(350%);opacity:.9}}
.lp .lp-footer-grid{grid-template-columns:1.15fr .65fr .85fr 1.1fr;gap:32px}
.lp .lp-feedback-email{display:inline-flex;align-items:center;gap:9px;margin-top:14px;color:#8be9f6;font-size:14px;overflow-wrap:anywhere;text-decoration:underline;text-underline-offset:4px}
.lp .lp-feedback-email svg{width:20px;height:20px}
.lp .lp-feedback-email:hover{color:#fff}
@media(max-width:1100px){.lp-hex{width:80px;height:94px}.lp .lp-footer-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:30px}}
@media(max-width:760px){.lp .lp-footer-grid{grid-template-columns:1fr}.lp-emblem{min-height:125px}.lp .lp-wave-art{opacity:.5}}
@media(max-width:390px){.lp-panel-top{grid-template-columns:1fr}.lp-emblem{padding:0;min-height:130px}.lp-hex{width:100px;height:114px}.lp-hex b{font-size:30px}}
@media(prefers-reduced-motion:reduce){.lp-wave-band,.lp-metrics:before{animation:none!important;will-change:auto}}


/* Latar gambar statis; satu titik bergerak persis pada tepi hexagon. */
.lp-panel{background-image:url("data:image/webp;base64,");background-size:cover;background-position:center;background-repeat:no-repeat}
.lp-panel-top>div:last-child{background:none;text-shadow:0 1px 5px #031a2bbb}
.lp-metrics:before{display:none}
.lp-hex-traced{width:112px;height:130px;filter:none}
.lp-hex-traced:before,.lp-hex-traced:after{display:none}
.lp .lp-hex-svg{display:block;width:100%;height:100%;overflow:visible}
.lp-metric,.lp-panel-foot{ text-shadow:0 1px 4px #031a2b99 }
@media(max-width:1100px){.lp-hex-traced{width:82px;height:96px}}
@media(max-width:390px){.lp-hex-traced{width:108px;height:124px}}
@media(prefers-reduced-motion:reduce){.lp-hex-runner{display:none}}


/* Panel tetap pada kolom kanan hero. Penyesuaian hanya di dalam kotak. */
.lp-panel{padding:30px 28px 22px;background-size:100% 100%;background-position:center}
.lp-panel-top{grid-template-columns:38% minmax(0,1fr);gap:22px;align-items:center;min-height:220px}
.lp-emblem{border:0;padding:0;min-height:0;align-items:center;justify-content:center}
.lp-hex-traced{width:132px;height:auto;max-width:100%;aspect-ratio:120/138;filter:none}
.lp .lp-hex-svg{width:100%;height:100%;overflow:visible}
.lp-panel-top>div:last-child{background:none;text-shadow:0 1px 5px #031a2b88;min-width:0}
.lp-panel-label{font-size:10px;letter-spacing:3.5px;margin:0 0 18px}
.lp-panel h2{font-size:clamp(24px,2.45vw,37px);line-height:1.1;letter-spacing:-1px;margin-bottom:20px}
.lp-panel-copy{font-size:14px;line-height:1.6;color:#bad7e5}
/* Garis tipis penuh dengan kilau memanjang yang diam seperti referensi. */
.lp-metrics{border-top:0;margin-top:24px;padding-top:25px;position:relative}
.lp-metrics:before{display:block;content:"";position:absolute;left:0;right:0;top:0;width:100%;height:1px;background:linear-gradient(90deg,transparent,#63d8ea77 8%,#63d8ea99 75%,transparent);filter:none;animation:none;transform:none;opacity:1}
.lp-metrics:after{content:"";position:absolute;left:17%;top:-1px;width:28%;height:3px;background:linear-gradient(90deg,transparent,#55e6f5 40%,#e0ffff 53%,#55e6f5 63%,transparent);filter:drop-shadow(0 0 5px #3beaff);pointer-events:none}
.lp-panel-foot{margin-top:27px}
@media(max-width:1100px) and (min-width:761px){.lp-panel{padding:25px 20px 20px}.lp-panel-top{grid-template-columns:33% minmax(0,1fr);gap:17px;min-height:200px}.lp-hex-traced{width:100px}.lp-panel h2{font-size:27px}.lp-panel-copy{font-size:12px}.lp-panel-label{font-size:9px;letter-spacing:2.5px}}
@media(max-width:760px){.lp-panel-top{grid-template-columns:34% minmax(0,1fr);gap:18px;min-height:200px}.lp-hex-traced{width:115px}.lp-panel h2{font-size:clamp(24px,5vw,34px)}.lp-panel-copy{font-size:13px}.lp-panel-label{font-size:9px;letter-spacing:2.3px}}
@media(max-width:390px){.lp-panel{padding:24px 16px 20px}.lp-panel-top{grid-template-columns:31% minmax(0,1fr);gap:14px;min-height:180px}.lp-hex-traced{width:95px}.lp-panel h2{font-size:23px;letter-spacing:-.6px;margin-bottom:14px}.lp-panel-copy{font-size:12px}.lp-panel-label{font-size:8px;letter-spacing:1.8px;margin-bottom:12px}}


/* Revisi: ruang logo lebih besar, teks prinsip lebih dekat sisi kanan. */
.lp-panel-top{grid-template-columns:43% minmax(0,1fr);gap:22px}
.lp-panel-top>div:last-child{padding-left:0}
.lp-metric:first-child>div{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:12px;align-items:center;min-width:0}
.lp-metric:first-child b{grid-column:1;grid-row:1}
.lp-metric:first-child p{grid-column:2;grid-row:1;margin:0;font-size:14px;white-space:nowrap}
.lp-metric:first-child small{grid-column:1/-1;grid-row:2;margin-top:8px}
@media(max-width:1100px) and (min-width:761px){.lp-panel-top{grid-template-columns:39% minmax(0,1fr);gap:17px}.lp-panel h2{font-size:25px}.lp-metric:first-child>div{column-gap:8px}.lp-metric:first-child p{font-size:12px}}
@media(max-width:760px){.lp-panel-top{grid-template-columns:39% minmax(0,1fr);gap:18px}.lp-panel h2{font-size:clamp(23px,4.6vw,32px)}}
@media(max-width:390px){.lp-panel-top{grid-template-columns:36% minmax(0,1fr);gap:14px}.lp-panel h2{font-size:22px}.lp-metric:first-child p{font-size:12px}.lp-metric:first-child>div{column-gap:8px}}


/* Palet navy–teal selaras dengan judul dan tombol landing. */
body.lp{color:#081d3b;background:#f3f9fc}
.lp-surface{background:radial-gradient(ellipse at 77% 24%,#bde9ed35,transparent 50%),linear-gradient(140deg,#f5faff,#f0f8fb)}
