.lp-panel h2 span{color:#65d8dd}
.lp-panel-label{color:#a4d8dd}
.lp-panel-copy{color:#c0d7df}
.lp-metric b,.lp-metric p{color:#f5fbfc}
.lp-metric>svg{color:#83d6dc}
