.lp-panel-foot{color:#9dbdc9}
.lp-hex-traced{filter:hue-rotate(-12deg) saturate(.8)}
.lp-eyebrow,.lp-lead,.lp-step p,.lp-role-card p,.lp-feature p{color:#637d91}
.lp-icon,.lp-number{color:#126477}
.lp .lp-site-footer{background:linear-gradient(125deg,#0b2d3b,#061b25)}
.lp .lp-feedback-email,.lp .lp-site-footer .lp-brand span{color:#8bdce0}

</style>
